const GENERIC = /(^|\.)(wikipedia\.org|wikimedia\.org|youtube\.com|youtu\.be|linkedin\.com|facebook\.com|instagram\.com|x\.com|twitter\.com|tiktok\.com|reddit\.com|quora\.com|medium\.com|github\.com|google\.com|goo\.gl|bing\.com|apple\.com|amazon\.com|forbes\.com|reuters\.com|bloomberg\.com|gulfnews\.com|khaleejtimes\.com|thenationalnews\.com|zawya\.com|arabianbusiness\.com|gartner\.com|g2\.com|capterra\.com|trustpilot\.com|clutch\.co|glassdoor\.com|indeed\.com|statista\.com|pwc\.com|kpmg\.com|deloitte\.com|ey\.com|vertexaisearch\.cloud\.google\.com|chatgpt\.com|openai\.com|perplexity\.ai|anthropic\.com|claude\.ai|gemini\.google\.com|gstatic\.com)$|\.gov(\.[a-z]{2})?$|\.edu(\.[a-z]{2})?$|\.ac\.[a-z]{2}$|(^|\.)u\.ae$|\.int$/i;
const esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const wordRe = (t) => new RegExp('(^|[^a-z0-9])' + esc(String(t).toLowerCase()) + '($|[^a-z0-9])', 'i');
const DB_ENGINES = /^(market|index_)/;
const rows = [];
reqs.forEach((q, i) => {
  if (DB_ENGINES.test(q.engine)) return;
  const plan = plans.find(p => p.site_id === q.site_id) || { brand_names: [q.domain], competitors: [], domain: q.domain, aliases: {} };
  const r = resps[i] || {}; const task = (r.tasks || [])[0] || {}; const res = (task.result || [])[0] || null;
  let text = '', cites = [], answered = false, error = '', fanout = [], entities = [];
  if (r.error || !task.status_code) error = String((r.error && (r.error.message || r.error)) || 'no response').slice(0, 200);
  else if (task.status_code !== 20000) error = String(task.status_message || task.status_code).slice(0, 200);
  else if (res) {
    fanout = (res.fan_out_queries || []).map(String).filter(Boolean);
    if (q.engine === 'chatgpt' || (q.engine === 'gemini' && (res.markdown != null || (res.items || []).some(x => /^gemini_/.test(String(x && x.type)))))) {   // LLM scraper: the real chat interface
      text = String(res.markdown || (res.items || []).map(x => x.markdown || x.text || '').join('\n'));
      cites = [...(res.sources || []), ...(res.items || []).flatMap(x => x.sources || [])].map(s => ({ url: s.url, title: s.title || '', host: hostOf(s.url) || String(s.domain || '').replace(/^www\./, '') }));
      entities = [...(res.brand_entities || []), ...(res.items || []).flatMap(x => x.brand_entities || [])].map(b => String((b && (b.title || b.markdown)) || '').trim()).filter(Boolean);
      answered = !!text;
    } else if (q.engine === 'ai_overview' || q.engine === 'ai_mode' || q.engine === 'copilot') {   // Copilot Search: the ai_overview item of Bing's results
      const ao = (res.items || []).find(x => x && x.type === 'ai_overview');
      if (ao) { text = String(ao.markdown || (ao.items || []).map(x => x.markdown || x.text || '').join('\n'));
        const refs = [...(ao.references || []), ...(ao.items || []).flatMap(x => x.references || [])];
        cites = refs.map(x => ({ url: x.url, title: x.title || x.source || '', host: hostOf(x.url) || String(x.domain || '').replace(/^www\./, '') })); answered = !!(text || cites.length); }
    } else {   // llm_responses: sections with text + annotations (Gemini annotations point to a Google redirect; their title is the source domain)
      const secs = (res.items || []).flatMap(it => it.sections || []);
      text = secs.map(s => s.text || '').join('');
      cites = secs.flatMap(s => s.annotations || []).map(a => { const direct = a.direct_url || ''; let h = hostOf(direct || a.url); if (/vertexaisearch\.cloud\.google\.com/.test(h) && /^[a-z0-9.-]+\.[a-z]{2,}$/i.test(String(a.title || '').trim())) h = String(a.title).trim().toLowerCase().replace(/^www\./, ''); return { url: direct || (/vertexaisearch/.test(String(a.url)) ? '' : a.url), title: /^[a-z0-9.-]+\.[a-z]{2,}$/i.test(String(a.title || '').trim()) ? '' : String(a.title || ''), host: h }; });
      answered = !!text;
    }
  }
  const low = text.toLowerCase().replace(/[?&](utm_[a-z]+|srsltid)=[^\s)&\]]*/g, '');   // ChatGPT tags every link with utm_source=chatgpt.com
  const brandRes = plan.brand_names.map(wordRe);
  const firstAt = (res_) => { let best = -1; for (const re of res_) { const m = low.match(re); if (m && (best < 0 || m.index < best)) best = m.index + (m[1] ? m[1].length : 0); } return best; };
  const ourAt = firstAt(brandRes);
  const isOurs = (h) => !!h && (h === plan.domain || h.endsWith('.' + plan.domain));
  const ourUrls = [...new Set(cites.filter(c => isOurs(c.host) && c.url).map(c => cleanUrl(c.url)))];
  const cited = cites.some(c => isOurs(c.host));
  const mentioned = ourAt >= 0 || cited;
  // businesses named in the answer: configured competitors (domain or name), brand names learned for them (aliases), the engine's own brand list,
  // and business domains written in the text or linked from it
  const named = new Map();
  const put = (d, at) => { if (!d || isOurs(d)) return; if (!named.has(d) || at < named.get(d)) named.set(d, at); };
  for (const c of plan.competitors) { const lab = c.split('.')[0]; const at = firstAt([wordRe(c), ...(lab.length >= 5 ? [wordRe(lab)] : [])]); if (at >= 0 || cites.some(x => x.host === c || x.host.endsWith('.' + c))) put(c, at >= 0 ? at : 1e9); }
  const ourNames = new Set(plan.brand_names.map(b => String(b).toLowerCase()));
  for (const [name, dom] of Object.entries(plan.aliases || {})) { if (String(name).length < 4 || ourNames.has(String(name).toLowerCase())) continue; const hasDom = !!(dom && /\./.test(dom)); if (!hasDom && !brandish(name)) continue; const at = firstAt([wordRe(name)]); if (at >= 0) put(hasDom ? dom : String(name), at); }   // D19: a name without a website must read like a business name
  for (const e of entities) { if (ourNames.has(e.toLowerCase()) || brandRes.some(re => re.test(e.toLowerCase()))) continue; const dom = Object.entries(plan.aliases || {}).find(([n]) => n.toLowerCase() === e.toLowerCase()); const known = !!(dom && /\./.test(dom[1])); if (!known && !brandish(e)) continue; const at = firstAt([wordRe(e)]); put(known ? dom[1] : e, at >= 0 ? at : 1e8); }   // D19: the engine's brand list also carries headings ("Tax technology and e-invoicing software"): only names count
  for (const m of low.matchAll(DOMAIN_RE)) { const d = m[1].replace(/^www\./, ''); if (isOurs(d) || GENERIC.test(d)) continue; put(d, m.index); }
  for (const c of cites) { const d = c.host; if (!d || isOurs(d) || GENERIC.test(d) || named.has(d)) continue; const lab = d.split('.')[0]; const at2 = lab.length >= 4 ? low.indexOf(lab) : -1; put(d, at2 >= 0 ? at2 : 1e9); }   // businesses cited as sources
  const others = [...mergeBrands([...named.entries()], plan.aliases).entries()].map(([k, v]) => [k, Math.min(...v)]).sort((a, b) => a[1] - b[1]);   // a brand name and its website are one business
  const rank = ourAt >= 0 ? 1 + others.filter(([, at]) => at < ourAt).length : 0;   // position among the businesses the answer names; 0 = not named (a citation alone is not a recommendation)
  const sources = [...new Set(cites.map(c => c.host).filter(Boolean))];
  // the exact third-party pages cited (not yours, not search engines): where to be named so the next answer names you
  const seenU = new Set(); const cited_urls = cites.filter(c => c.url && c.host && !isOurs(c.host) && !/(^|\.)(google|bing|vertexaisearch\.cloud\.google)\.com$/.test(c.host)).map(c => ({ u: cleanUrl(c.url).slice(0, 300), t: citeTitle(c.title) })).filter(c => !seenU.has(c.u) && seenU.add(c.u)).slice(0, 8);
  const at = ourAt >= 0 ? ourAt : 0;
  const short = q.run_kind === 'pulse';
  const excerpt = text ? text.slice(Math.max(0, at - 160), at + (short ? 200 : 340)).replace(/\s+/g, ' ').trim() : '';
  const brands = [...(ourAt >= 0 ? [[plan.brand_names.find(b => !/\./.test(b)) || plan.domain, ourAt]] : []), ...others.filter(([, a]) => a < 1e9)].sort((a, b) => a[1] - b[1]).map(([d]) => d);
  rows.push({ site_id: q.site_id, domain: q.domain, run_id: q.run_id, checked_at: now, prompt_id: q.prompt_id, prompt: q.prompt, kind: q.kind, topic: q.topic || '', engine: q.engine,
    answered, mentioned: answered && mentioned, cited: answered && cited, rank: answered ? rank : 0, our_urls: ourUrls.join(' '), competitors: others.map(([d]) => d).slice(0, 12).join(', '),
    sources: sources.slice(0, 15).join(', '), excerpt: excerpt.slice(0, short ? 360 : 520), cost: Number(task.cost) || 0, error,
    run_kind: q.run_kind || 'weekly', sentiment: '', brands: brands.slice(0, 12).join(', '), issues: '', fanout: fanout.slice(0, 6).join(' | ').slice(0, 600), cited_urls: cited_urls.length ? JSON.stringify(cited_urls) : '',
    _text: answered ? text.replace(/\s+/g, ' ').slice(0, 2400) : '' });
});
return rows.length ? rows.map(r => ({ json: r })) : [{ json: { skip: true } }];

// Answer Analyst jobs (v4.9, weekly and on-demand runs): Claude reads the answers that matter — every answer naming the business, the brand question,
// and the recommendation / comparison answers — and returns per answer the businesses named in order (with their website when known), how the
// answer speaks of the business (sentiment) and any claim about it that contradicts the business profile (wrong city, services, prices, a
// different company with the same name). Regex matching cannot see a competitor named without its website, or a wrong fact; this can.
// 12 answers per job, at most 6 jobs per site and 24 per run (~$0.02 each; the agent runs them one after another, so the cap keeps a
// many-site run inside the execution time limit — sites past it keep the parser's reading this week).
// G6 (2026-10-18): a bigger panel reads more answers — the site's share is the panel's Answer Analyst budget (AIP.analystCap: 24 + 1 per 25
// questions, at most 60 a run) spread over the executions the run is split into, so a 500-question run reads ~44 jobs' worth in all, not 6.
// One execution never starts more than 36 (the agent runs them one after another, ~25 s each, inside the execution time limit).
const CONFIG = { per_job: 12, max_jobs_per_site: 6, max_jobs_per_run: 36, chars: 1500, min_facts: 2 };   // min_facts (G10): fewer checkable facts than this and the wrong-claim check is reported as "not checked"
const plans = $('AI Plan').all().map(i => i.json).filter(p => !p.nothing_to_do && !p.pulse_run);
let rows = []; try { rows = $('Parse AI Answers').all().map(i => i.json).filter(r => !r.skip && r.engine && r.answered && r._text); } catch (e) {}
const out = [];
for (const p of plans) {
  const mine = rows.filter(r => r.site_id === p.site_id);
  const pick = [...mine.filter(r => r.mentioned || r.kind === 'brand'), ...mine.filter(r => !r.mentioned && r.kind !== 'brand' && ['recommend', 'compare', 'choose', 'custom'].includes(r.kind))];
  const cm = p.cost_model || {}; const share = cm.analyst_jobs ? Math.ceil(Number(cm.analyst_jobs) / Math.max(1, Number(cm.executions) || 1)) : CONFIG.max_jobs_per_site;
  const sel = pick.slice(0, CONFIG.per_job * Math.max(1, Math.min(12, Math.max(CONFIG.max_jobs_per_site, share))));
  const P = p.profile || {};
  // G10 (2026-10-11 system review): the fact sheet the analyst checks the answers against — the business profile (seo_profiles), the
  // facts and services of the site model (SITE_MODEL_SPEC.md) and the accreditation status. A claim can only be called wrong against a
  // fact on file, so a sheet with fewer than CONFIG.min_facts checkable facts switches the check OFF: the run then reports "not
  // checked" instead of "no wrong claims" (the website alone says nothing about a city, a service or a price).
  const sheet = [['Business name', p.business_name], ['Website', p.domain], ['Type', p.business_type], ['City', P.city], ['Region', P.region], ['Country', p.country], ['Address', P.street_address], ['Phone', P.phone], ['E-mail', P.public_email],
    ['Price range', P.price_range], ['Areas served', P.service_areas], ['Opening hours', P.opening_hours], ['Services on the site', (p.services || []).join(', ')], ['Topics', (p.topics || []).join(', ')],
    ['Accreditation', p.accreditation], ['Other facts', String(p.business_facts || '').slice(0, 900)], ['Other names', (p.brand_names || []).filter(b => !/\./.test(b)).join(', ')]].filter(([, v]) => v);
  const CHECKABLE = ['City', 'Region', 'Country', 'Address', 'Phone', 'E-mail', 'Price range', 'Areas served', 'Opening hours', 'Services on the site', 'Accreditation', 'Other facts', 'Type'];
  // P34-3 (live 2026-10-12): two checkable entries were met by Country (the site's tracked market) and "Services on the site" (read off
  // the site by the site model) alone, so with an empty business profile the run still reported "no claim was wrong" about a
  // "Dubai-based" description that nothing on file could judge. A claim is only checkable against a fact the owner put on file, and a
  // place has to be among them: without a city, a region, an address or a phone number nothing locates the business, and most wrong
  // claims are about where it is and what it charges. Country, services and topics stay on the sheet as context — they never switch
  // the check on by themselves.
  const OWNER = ['City', 'Region', 'Address', 'Phone', 'E-mail', 'Price range', 'Areas served', 'Opening hours', 'Accreditation', 'Other facts', 'Type'];   // seo_profiles + the business facts the app sends
  const LOCATING = ['City', 'Region', 'Address', 'Phone'];
  const owner_facts = sheet.filter(([k]) => OWNER.includes(k)).length;
  const located = sheet.some(([k]) => LOCATING.includes(k));
  const facts_ok = sheet.filter(([k]) => CHECKABLE.includes(k)).length >= CONFIG.min_facts && owner_facts >= CONFIG.min_facts && located;
